@startuml

class School {
  + name : string
}

class Person {
  + firstName : string
  + lastName : string
}

class Teacher extends Person {
  + email : string
}

class Student extends Person {
}

class TeachingAssignment {
  + hours : int
}

class ClassGroup {
  + name : string
}

class Room {
  + name : string
}

class Classroom extends Room {
  + capacity : int
}

class Gym extends Room {
  + size : float
}

School "1" -- "*" Teacher : employs
School "1" -- "0..3" Teacher : employs via teaching assignment
Teacher "1" -- "0..1" School : principal of

Teacher "1" -- "*" TeachingAssignment : performs
School "1" -- "*" TeachingAssignment : has

Student "*" -- "1" ClassGroup : belongs to
ClassGroup "1" -- "1" Classroom : assigned to
Classroom "1" -- "1" ClassGroup : assigned to

@enduml

